import{_ as t,o as e,c as l,ag as i}from"./chunks/framework.-Wrcbzkw.js";const g=JSON.parse('{"title":"D2C 知识检索 Agent 设计","description":"","frontmatter":{},"headers":[],"relativePath":"project/D2C/知识检索Agent设计.md","filePath":"project/D2C/知识检索Agent设计.md","lastUpdated":1781078576000}'),n={name:"project/D2C/知识检索Agent设计.md"};function s(d,a,r,p,o,c){return e(),l("div",null,[...a[0]||(a[0]=[i(`<h1 id="d2c-知识检索-agent-设计" tabindex="-1">D2C 知识检索 Agent 设计 <a class="header-anchor" href="#d2c-知识检索-agent-设计" aria-label="Permalink to &quot;D2C 知识检索 Agent 设计&quot;">​</a></h1><p>知识检索 Agent 是 D2C 流水线的第三个阶段。它根据组件 DSL，从知识库中检索当前项目使用的组件库文档、代码规范和示例，并将这些资料提供给代码生成 Agent。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>组件 DSL -&gt; 知识检索 Agent -&gt; DSL + 项目知识</span></span></code></pre></div><h2 id="一、为什么模型自身知识不够" tabindex="-1">一、为什么模型自身知识不够 <a class="header-anchor" href="#一、为什么模型自身知识不够" aria-label="Permalink to &quot;一、为什么模型自身知识不够&quot;">​</a></h2><p>大模型可能了解 React、Vue 和常见 UI 组件，但它通常不知道当前项目的真实约束，例如：</p><ul><li>项目使用哪个组件库及具体版本</li><li>内部组件有哪些属性和插槽</li><li>组件应该从哪个路径导入</li><li>团队规定使用哪些样式方案</li><li>表单、弹窗和请求如何封装</li><li>项目中已有的组件示例</li></ul><p>如果仅依赖模型参数知识，生成代码可能语法正确，却无法在真实项目中运行。</p><h2 id="二、知识检索-agent-的设计目标" tabindex="-1">二、知识检索 Agent 的设计目标 <a class="header-anchor" href="#二、知识检索-agent-的设计目标" aria-label="Permalink to &quot;二、知识检索 Agent 的设计目标&quot;">​</a></h2><ol><li>从 DSL 中识别需要的组件与能力</li><li>为每类组件构造检索查询</li><li>从向量数据库中召回相关资料</li><li>对资料进行过滤、排序和去重</li><li>将准确、有限的上下文交给代码生成阶段</li></ol><p>例如，DSL 中出现表单和日期选择需求时，检索 Agent 可以提供项目中 <code>Form</code>、<code>DatePicker</code> 的 API 文档与示例。</p><h2 id="三、为什么需要独立检索阶段" tabindex="-1">三、为什么需要独立检索阶段 <a class="header-anchor" href="#三、为什么需要独立检索阶段" aria-label="Permalink to &quot;三、为什么需要独立检索阶段&quot;">​</a></h2><p>如果让代码生成 Agent 同时搜索资料和生成代码，会出现以下问题：</p><ul><li>检索过程难以观察和调试</li><li>无法判断错误来自资料召回还是代码生成</li><li>同一组件文档会被重复检索</li><li>很难单独评估检索准确率</li><li>生成模型可能忽略检索动作，凭记忆编写代码</li></ul><p>独立检索阶段可以缓存结果，并明确记录每个组件使用了哪些知识来源。</p><h2 id="四、为什么使用-rag" tabindex="-1">四、为什么使用 RAG <a class="header-anchor" href="#四、为什么使用-rag" aria-label="Permalink to &quot;四、为什么使用 RAG&quot;">​</a></h2><p>组件库和项目规范会不断变化，不适合全部写入模型参数。RAG 可以在不重新训练模型的情况下更新知识。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>组件文档</span></span>
<span class="line"><span>  -&gt; 分块与向量化</span></span>
<span class="line"><span>  -&gt; ChromaDB</span></span>
<span class="line"><span>  -&gt; 根据 DSL 召回相关资料</span></span>
<span class="line"><span>  -&gt; 提供给代码生成 Agent</span></span></code></pre></div><p>与微调相比，RAG 更适合保存需要频繁更新、需要引用来源的项目知识。</p><h2 id="五、检索内容应该包含什么" tabindex="-1">五、检索内容应该包含什么 <a class="header-anchor" href="#五、检索内容应该包含什么" aria-label="Permalink to &quot;五、检索内容应该包含什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>知识类型</th><th>示例</th></tr></thead><tbody><tr><td>组件 API</td><td>属性、事件、插槽、导入路径</td></tr><tr><td>使用示例</td><td>表单、列表、弹窗的真实代码</td></tr><tr><td>项目规范</td><td>命名规则、目录结构、样式约束</td></tr><tr><td>业务组件</td><td>内部组件用途与调用方式</td></tr><tr><td>错误经验</td><td>常见错误与修复方法</td></tr></tbody></table><p>检索结果应尽量简洁、准确。召回过多无关文档会占用上下文，并干扰代码生成。</p><h2 id="六、失败风险与验证方式" tabindex="-1">六、失败风险与验证方式 <a class="header-anchor" href="#六、失败风险与验证方式" aria-label="Permalink to &quot;六、失败风险与验证方式&quot;">​</a></h2><p>常见失败包括：</p><ul><li>DSL 组件名称过于模糊，无法形成准确查询</li><li>召回了旧版本文档</li><li>相似度高但实际无关</li><li>重要组件文档没有被召回</li><li>多份资料互相冲突</li></ul><p>可以通过 Recall@K、人工标注查询集、版本元数据过滤、重排序和来源引用检查评估检索质量。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>知识检索 Agent 负责把通用大模型连接到当前项目的真实技术环境。它让代码生成阶段不再只依赖模型记忆，而是基于最新组件文档、项目规范和真实示例生成代码。</p>`,27)])])}const u=t(n,[["render",s]]);export{g as __pageData,u as default};
